void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;  // More aggressive threshold reduction
    rephase_limit += 4096;  // Smaller increment to trigger rephase more frequently

    // Implement a phased rephasing strategy similar to restart's phase saving
    int phase_rand = rand() % 100;
    if ((phase_rand -= 50) < 0) {
        // 50%: Save current trail state as phases
        for (int i = 1; i <= vars; i++) 
            saved[i] = (value[i] != 0) ? value[i] : saved[i];
    } else if ((phase_rand -= 30) < 0) {
        // 30%: Invert current trail state
        for (int i = 1; i <= vars; i++) 
            saved[i] = (value[i] != 0) ? -value[i] : -saved[i];
    } else if ((phase_rand -= 15) < 0) {
        // 15%: Use local best phases
        for (int i = 1; i <= vars; i++) saved[i] = local_best[i];
    } else {
        // 5%: Random phases
        for (int i = 1; i <= vars; i++) 
            saved[i] = (rand() % 2) ? 1 : -1;
    }
}
